import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as s,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Copilot Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/copilot/copilot-glossary.md","filePath":"products/ai-coding/copilot/copilot-glossary.md","lastUpdated":1787046041000}'),n={name:"products/ai-coding/copilot/copilot-glossary.md"};function r(i,t,l,d,c,p){return s(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="copilot-glossary" tabindex="-1">Copilot Glossary <a class="header-anchor" href="#copilot-glossary" aria-label="Permalink to &quot;Copilot Glossary&quot;">​</a></h1><blockquote><p>This is an <strong>explanation</strong> page — &quot;what is this, why does it exist, how does it relate?&quot; It pairs with the <a href="./copilot-cheatsheet.html">Cheatsheet</a>: that page answers &quot;how do I configure it / what is the flag?&quot; This page answers &quot;what is it / why do I need it / how does it talk to the other concepts?&quot;</p><p>Shared terms are defined <strong>once here</strong>. The <a href="./copilot.html">tutorial</a> and <a href="./copilot-cookbook.html">Cookbook</a> link here instead of restating.</p><p>Copilot retires names quickly. The last section, <a href="#retired-or-renamed-concepts">Retired or renamed concepts</a>, is the parking lot for &quot;you saw this in an old tutorial, including our old single file, and it is gone.&quot;</p></blockquote><h2 id="concept-map" tabindex="-1">Concept map <a class="header-anchor" href="#concept-map" aria-label="Permalink to &quot;Concept map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌────────────────────────┐</span></span>
<span class="line"><span>                    │     GitHub Copilot     │  ← subscription layer:</span></span>
<span class="line"><span>                    │     plan / quota       │     which surfaces and models</span></span>
<span class="line"><span>                    └───────────┬────────────┘</span></span>
<span class="line"><span>                                │</span></span>
<span class="line"><span>        ┌──────────────┬────────┴───────┬─────────────────┐</span></span>
<span class="line"><span>        │              │                │                 │</span></span>
<span class="line"><span>   ┌────┴─────┐  ┌────┴─────┐    ┌────┴─────┐     ┌─────┴──────┐</span></span>
<span class="line"><span>   │ Completion│  │   Chat   │    │   CLI    │     │ Cloud agent │  ← surface layer</span></span>
<span class="line"><span>   │ (inline) │  │ (in IDE)  │    │ (terminal)│     │ (on GitHub) │</span></span>
<span class="line"><span>   └──────────┘  └────┬─────┘    └────┬─────┘     └──────┬─────┘</span></span>
<span class="line"><span>                      │               │                  │</span></span>
<span class="line"><span>                      └───────┬───────┴──────────────────┘</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>              ┌───────────────┴────────────────┐</span></span>
<span class="line"><span>              │     Context &amp; customization    │  ← what you write, what it sees</span></span>
<span class="line"><span>              ├────────────────────────────────┤</span></span>
<span class="line"><span>              │ Instructions  Prompt files     │</span></span>
<span class="line"><span>              │ Custom agents  Skills  Plugins │</span></span>
<span class="line"><span>              │ MCP   Spaces                   │</span></span>
<span class="line"><span>              └────────────────────────────────┘</span></span></code></pre></div><p><strong>The logic</strong>: the <strong>subscription layer</strong> decides quota and models. The <strong>surface layer</strong> is four doors — completion while you type, Chat in the IDE, CLI in the terminal, Cloud agent in the background on GitHub. <strong>Context &amp; customization</strong> cuts across every door and decides what Copilot actually &quot;knows.&quot; Ninety percent of leverage is on the third layer. Switching surfaces is a posture change; feeding context is a skill change.</p><hr><h2 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h2><p><strong>What it is</strong>: GitHub&#39;s AI coding assistant. Editor extensions, a CLI, and github.com all sit on large language models to help you write, explain, and run development work.</p><p><strong>It is not &quot;ChatGPT plus your repository.&quot;</strong> That is the most common misconception — and the sentence our old single file used. Copilot is not bound to one model. The <a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">plans page</a> lists different model catalogs per subscription; paid plans can switch vendors, Free is auto-selection only. &quot;It knows your project&quot; is <strong>retrieval-based context injection</strong>, not &quot;we trained on your repo&quot;: the editor packs the current file, open tabs, files you cite, and tool results into each request. That is why &quot;open the relevant files&quot; and &quot;write custom instructions&quot; improve output immediately, and why &quot;our repo is huge so Copilot must understand it&quot; is wrong.</p><p><strong>Why learn it as a system</strong>: Tab-complete is the easiest surface and the fastest ceiling. The real gap is controlling context, picking a surface, and turning repeated demands into files. That is why this set is four Diataxis pages, not one.</p><p><strong>Official</strong>:</p><ul><li><a href="https://docs.github.com/en/copilot" target="_blank" rel="noreferrer">Copilot docs home</a></li><li><a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">Plans</a></li><li><a href="https://github.blog/ai-and-ml/github-copilot/how-github-copilot-is-getting-better-at-understanding-your-code/" target="_blank" rel="noreferrer">How GitHub Copilot is getting better at understanding your code</a></li></ul><hr><h2 id="prompt-prompt-engineering-context" tabindex="-1">Prompt / Prompt Engineering / Context <a class="header-anchor" href="#prompt-prompt-engineering-context" aria-label="Permalink to &quot;Prompt / Prompt Engineering / Context&quot;">​</a></h2><p><strong>What they are</strong>:</p><ul><li><strong>Prompt</strong>: the input you send the model.</li><li><strong>Prompt Engineering</strong>: how you organize that input so the model does what you meant.</li><li><strong>Context</strong>: extra information you attach so the model can understand the question.</li></ul><p><strong>In Copilot specifically</strong>:</p><table tabindex="0"><thead><tr><th>Role</th><th>Prompt is</th><th>Prompt Engineering is</th><th>Context is</th></tr></thead><tbody><tr><td>Developer</td><td>A code block, an inline comment, or a Chat question</td><td>Improving comments and questions so suggestions get better</td><td>Extra information injected via participants (<code>@</code>), tools (<code>#</code>), or explicit file cites</td></tr></tbody></table><blockquote><p>Table adapted from <a href="https://github.blog/developer-skills/github/how-to-write-better-prompts-for-github-copilot/#whats-a-prompt-and-what-is-prompt-engineering" target="_blank" rel="noreferrer">How to use GitHub Copilot: Prompts, tips, and use cases</a>.</p></blockquote><p><strong>Why split the three</strong>: beginners blame the model when Copilot &quot;doesn&#39;t get it.&quot; About eight times out of ten the context is missing — files closed, nothing cited, no instructions. Split the terms and the debug path is: context first, then prompt clarity, then the model.</p><p><strong>How to write them</strong>: <a href="./copilot-cookbook.html">Cookbook · Prompting principles</a>.</p><p><strong>Further reading</strong>:</p><ul><li><a href="https://dev.to/github/a-beginners-guide-to-prompt-engineering-with-github-copilot-3ibp" target="_blank" rel="noreferrer">A Beginner&#39;s Guide to Prompt Engineering with GitHub Copilot</a></li><li><a href="https://learn.deeplearning.ai/courses/chatgpt-prompt-eng/lesson/1/introduction" target="_blank" rel="noreferrer">ChatGPT Prompt Engineering for Developers</a></li></ul><hr><h2 id="four-surfaces" tabindex="-1">Four surfaces <a class="header-anchor" href="#four-surfaces" aria-label="Permalink to &quot;Four surfaces&quot;">​</a></h2><p><strong>What they are</strong>: Copilot is four classes of entry point, not one UI. Picking the wrong one is the common efficiency loss.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Where</th><th>Interaction</th><th>Typical job</th></tr></thead><tbody><tr><td><strong>Code completion (inline)</strong></td><td>Wherever you type</td><td>Type → ghost text → <code>Tab</code></td><td>Next line, boilerplate</td></tr><tr><td><strong>Chat</strong></td><td>Sidebar / inline / terminal</td><td>Conversation</td><td>Explain, refactor, multi-file edits</td></tr><tr><td><strong>CLI</strong></td><td>Terminal</td><td>Interactive agent session</td><td>Shell work, scripts, cross-repo tasks</td></tr><tr><td><strong>Cloud agent</strong></td><td>github.com / an Issue</td><td>Delegate; it runs in the background</td><td>A well-defined standalone job</td></tr></tbody></table><p>Two more official doors, used less often on day one (see the <a href="./">learning map</a>):</p><table tabindex="0"><thead><tr><th>Surface</th><th>Where</th><th>Typical job</th></tr></thead><tbody><tr><td><strong>Copilot Chat on github.com</strong></td><td>Browser</td><td>Ask about a repo / Issue / PR without opening an IDE</td></tr><tr><td><strong>Copilot app</strong></td><td>Desktop</td><td>Parallel agent sessions, Issues / PRs, automations</td></tr></tbody></table><p><strong>Why four instead of &quot;one Copilot&quot;</strong>: three axes differ — <strong>who starts</strong> (you type / you ask / you delegate), <strong>where it runs</strong> (local / GitHub cloud), <strong>what the artifact is</strong> (ghost text / editor diff / Pull Request). Mismatch hurts: completion for a refactor (cannot touch many files), Chat for a 20-minute migration (you have to watch).</p><p><strong>How to choose</strong>: <a href="./copilot-cheatsheet.html">Cheatsheet · Surface selection</a>.</p><hr><h2 id="ask-edit-agent" tabindex="-1">Ask / Edit / Agent <a class="header-anchor" href="#ask-edit-agent" aria-label="Permalink to &quot;Ask / Edit / Agent&quot;">​</a></h2><p><strong>What they are</strong>: three autonomy levels inside Chat.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Copilot may</th><th>Your control</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Ask</strong></td><td>Answer only; never edit</td><td>Full — it only talks</td><td>Concepts, explanations, plans</td></tr><tr><td><strong>Edit</strong></td><td>Change the files you name</td><td>You pick files, preview diffs, accept or discard</td><td>Controlled edits to known files</td></tr><tr><td><strong>Agent</strong></td><td>Choose files, propose and run commands, iterate</td><td>You approve tool calls and the final result</td><td>Multi-step work that needs tests or installs</td></tr></tbody></table><p><strong>Example prompts</strong>:</p><ul><li>Ask: &quot;What is the difference between let, const, and var in JavaScript?&quot; / &quot;Explain this function.&quot;</li><li>Edit: &quot;Refactor <code>calculateTotal</code> for readability.&quot; / &quot;<code>login</code> is broken; debug it.&quot;</li><li>Agent: &quot;Split this logic into several functions.&quot; / &quot;Run all tests and the linter for payment-processing.&quot;</li></ul><p><strong>Why three levels, not one autopilot</strong>: autonomy trades off against control. Agent mode is cheap in attention and expensive in surprise diffs when you do not know the code yet. Ask is safest and slowest. <strong>The test is &quot;can I see that it is wrong at a glance?&quot;</strong> Yes → Agent. No → Edit or Ask.</p><p><strong>Mode name ≠ product name</strong>: Agent <strong>mode</strong> is a Chat setting (local). Cloud <strong>agent</strong> is a separate cloud product. Easy to mix.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/get-started/best-practices" target="_blank" rel="noreferrer">Copilot best practices</a> · <a href="https://docs.github.com/en/copilot/concepts/chat" target="_blank" rel="noreferrer">About Copilot Chat</a></p><hr><h2 id="chat-participant" tabindex="-1">Chat participant <a class="header-anchor" href="#chat-participant" aria-label="Permalink to &quot;Chat participant&quot;">​</a></h2><p><strong>What it is</strong>: an <code>@</code>-prefixed &quot;specialist&quot; in Chat. It pins the question to a domain and injects that domain&#39;s context.</p><p><strong>Current VS Code built-ins</strong>:</p><table tabindex="0"><thead><tr><th>Participant</th><th>Context it injects</th><th>Example</th></tr></thead><tbody><tr><td><code>@github</code></td><td>GitHub (repos, Issues, PRs)</td><td><code>@github which open bug issues landed this week</code></td></tr><tr><td><code>@terminal</code></td><td>Integrated terminal and its contents</td><td><code>@terminal find the largest file in the src directory</code></td></tr><tr><td><code>@vscode</code></td><td>VS Code commands and features</td><td><code>@vscode how do I change my colors</code></td></tr></tbody></table><p>Extensions can add more. Full list: <a href="./copilot-cheatsheet.html">Cheatsheet · Chat participants</a>.</p><p><strong>Why the list shrank</strong>: early Copilot used participants as capability switches (<code>@workspace</code> = &quot;search the codebase&quot;). Those capabilities sank into <strong>tools</strong>. Agent mode decides whether to search. Participants are now a few domains you still have to name explicitly. That is why <code>@workspace</code> disappeared (see <a href="#retired-or-renamed-concepts">retired concepts</a>).</p><p><strong>Official</strong>: <a href="https://code.visualstudio.com/docs/copilot/reference/copilot-vscode-features" target="_blank" rel="noreferrer">VS Code Copilot feature reference</a></p><hr><h2 id="tools-tool-sets" tabindex="-1">Tools / tool sets <a class="header-anchor" href="#tools-tool-sets" aria-label="Permalink to &quot;Tools / tool sets&quot;">​</a></h2><p><strong>What they are</strong>: callable capabilities in Chat, cited with <code>#</code>. Related tools are packed into a <strong>tool set</strong> — <code>#read</code> allows <code>/readFile</code>, <code>/problems</code>, <code>/terminalLastCommand</code>, …</p><p><strong>Common sets</strong>:</p><table tabindex="0"><thead><tr><th>Set</th><th>Covers</th></tr></thead><tbody><tr><td><code>#read</code></td><td>Files, diagnostics, last terminal command, terminal selection</td></tr><tr><td><code>#edit</code></td><td>Create dirs/files, edit files and notebooks</td></tr><tr><td><code>#execute</code></td><td>Tasks, terminal commands, notebook cells, test failures</td></tr><tr><td><code>#search</code></td><td>Semantic codebase search, file search, text search, usages, SCM changes</td></tr><tr><td><code>#vscode</code></td><td>Install extensions, run VS Code commands, VS Code API</td></tr><tr><td><code>#web</code></td><td>Fetch a page</td></tr></tbody></table><p>Full list: <a href="./copilot-cheatsheet.html">Cheatsheet · Tool sets</a>.</p><p><strong>Why &quot;chat variables&quot; became &quot;tool sets&quot;</strong>: <code>#file</code> and <code>#selection</code> were <strong>static</strong> — paste a blob into the prompt once. Tools are <strong>actions</strong> — Copilot decides whether to call them, how often, and what to do with the result. That shift is agentification: static variables cannot explore; tools can.</p><p><strong>Relationship to MCP</strong>: MCP servers show up as tools in the same <code>#</code> list. <code>#</code> is the single tool door.</p><p><strong>Official</strong>: <a href="https://code.visualstudio.com/docs/copilot/reference/copilot-vscode-features" target="_blank" rel="noreferrer">VS Code Copilot feature reference</a></p><hr><h2 id="customization" tabindex="-1">Customization <a class="header-anchor" href="#customization" aria-label="Permalink to &quot;Customization&quot;">​</a></h2><p><strong>What it is</strong>: turn &quot;I have to say this every time&quot; into a file or setting Copilot attaches for you.</p><p><strong>Three mechanisms, by scope × trigger</strong>:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Scope</th><th>Trigger</th><th>Solves</th></tr></thead><tbody><tr><td><strong>Custom instructions</strong></td><td>Project- or path-level; every conversation</td><td>Automatic</td><td>Constant constraints (&quot;TypeScript strict&quot;, &quot;no class components&quot;)</td></tr><tr><td><strong>Prompt files</strong></td><td>One task</td><td>You type <code>/name</code></td><td>A reusable whole job (&quot;generate a React form from the template&quot;)</td></tr><tr><td><strong>Custom agents</strong></td><td>A whole conversation</td><td>You switch to that agent</td><td>A role switch (&quot;you are a security reviewer&quot;)</td></tr></tbody></table><p><strong>Why three</strong>: different <strong>lifecycles</strong>. Instructions are the project constitution. Prompt files are on-demand scripts. Custom agents are a persona for the whole thread. Put a constant constraint in a prompt file and you must remember to invoke it. Put a one-off task in instructions and you pollute every unrelated chat.</p><p><strong>Where the files go</strong>: <a href="./copilot-cheatsheet.html">Cheatsheet · Custom instructions</a> and <a href="./copilot-cookbook.html">Cookbook · Prompt files</a>.</p><p><strong>Official</strong>:</p><ul><li><a href="https://docs.github.com/en/copilot/reference/custom-instructions-support" target="_blank" rel="noreferrer">Custom instructions support</a></li><li><a href="https://code.visualstudio.com/docs/copilot/customization/overview" target="_blank" rel="noreferrer">VS Code Copilot customization</a></li></ul><hr><h2 id="custom-instructions" tabindex="-1">Custom instructions <a class="header-anchor" href="#custom-instructions" aria-label="Permalink to &quot;Custom instructions&quot;">​</a></h2><p><strong>What they are</strong>: Markdown that says &quot;in this project / this class of files, obey these rules.&quot; Copilot attaches them to every request.</p><p><strong>Five official scopes</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Scope</th></tr></thead><tbody><tr><td>👤 <strong>Personal</strong></td><td>All of your projects</td></tr><tr><td>📦 <strong>Repository-wide</strong></td><td>Every conversation in one repo</td></tr><tr><td>📂 <strong>Path-specific</strong></td><td>Files matching a glob</td></tr><tr><td>🤖 <strong>Agent</strong></td><td>Cross-tool agent files (<code>AGENTS.md</code>, …)</td></tr><tr><td>🏢 <strong>Organization</strong></td><td>Every repo in the org</td></tr></tbody></table><p>Paths and per-IDE support: <a href="./copilot-cheatsheet.html">Cheatsheet · Custom instructions</a>.</p><p><strong>Why this is the highest-ROI habit</strong>: it is the only &quot;write once, every later turn benefits&quot; mechanism. Ten precise project constraints beat restating the stack in every prompt.</p><p><strong>Versus <code>AGENTS.md</code></strong>: <code>.github/copilot-instructions.md</code> is Copilot-specific. <code>AGENTS.md</code> is a cross-tool convention file that Copilot also reads. Write <code>AGENTS.md</code> when several AI tools should share the same constitution. Write <code>copilot-instructions.md</code> when you need Copilot-only syntax.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/reference/custom-instructions-support" target="_blank" rel="noreferrer">Custom instructions support</a></p><hr><h2 id="prompt-files" tabindex="-1">Prompt files <a class="header-anchor" href="#prompt-files" aria-label="Permalink to &quot;Prompt files&quot;">​</a></h2><p><strong>What they are</strong>: <code>.prompt.md</code> files that store a complete reusable task. Invoke them in Chat as a slash command, with arguments.</p><p><strong>Versus custom instructions</strong>:</p><table tabindex="0"><thead><tr><th>Axis</th><th>Custom instructions</th><th>Prompt files</th></tr></thead><tbody><tr><td>Trigger</td><td>Automatic, every turn</td><td>Manual, <code>/name</code></td></tr><tr><td>Content</td><td>Constraints (&quot;no <code>any</code>&quot;)</td><td>A task (&quot;generate a validated form component&quot;)</td></tr><tr><td>Analogy</td><td>Project ESLint config</td><td>A snippet / script</td></tr></tbody></table><p><strong>Why they exist</strong>: every team has a handful of &quot;we re-describe this every time&quot; jobs — scaffold a component, write a migration, format a changelog. Prompt files make those Git-committable, shared, parameterized assets.</p><p><strong>Shape and authoring</strong>: <a href="./copilot-cookbook.html">Cookbook · Prompt files</a>.</p><p><strong>Official</strong>: <a href="https://code.visualstudio.com/docs/copilot/customization/overview" target="_blank" rel="noreferrer">VS Code Copilot customization</a></p><hr><h2 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h2><p><strong>What they are</strong>: a directory that packs the knowledge for one specialty (instructions, scripts, references). Copilot loads it when it recognizes a matching task.</p><p><strong>Versus prompt files</strong>: a prompt file is <strong>one Markdown file</strong> you invoke. A Skill is a <strong>directory with assets</strong> that can load automatically and can hold multi-file workflows plus helper scripts. Upgrade to a Skill when one file is not enough or you need accompanying scripts.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/concepts/agents/about-agent-skills" target="_blank" rel="noreferrer">About Agent Skills</a></p><hr><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><p><strong>What they are</strong>: installable packages that extend Copilot with reusable agents, skills, hooks, and integrations. Managed from Copilot CLI (<code>copilot plugin</code> / <code>copilot plugins …</code>) and from Chat (<code>/plugins</code>).</p><p><strong>What they are not</strong>: the <strong>GitHub App Copilot Extensions</strong> that sunset on 2025-11-10. Those were <code>@extension-name</code> Chat add-ons. Plugins are a later packaging format. If a 2024 blog says &quot;build a Copilot Extension,&quot; it is talking about the dead product.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/concepts/agents/about-plugins" target="_blank" rel="noreferrer">About GitHub Copilot plugins</a></p><hr><h2 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h2><p><strong>What it is</strong>: an open protocol for how AI apps talk to external tools and data. Build the server once; every MCP-capable host can use it.</p><p><strong>Why Copilot bet on it</strong>: not a guess — the official <a href="https://github.blog/changelog/2025-09-24-deprecate-github-copilot-extensions-github-apps/" target="_blank" rel="noreferrer">Extensions sunset notice</a> says Extensions only worked inside Copilot Chat, so tool authors had to rebuild for every other assistant. MCP is &quot;build once, reuse across hosts.&quot;</p><p><strong>How it shows up</strong>: MCP capabilities appear as <strong>tools</strong>, cited with <code>#</code>, indistinguishable from built-ins in daily use. Orgs can enable / disable / allowlist servers.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/concepts/context/mcp" target="_blank" rel="noreferrer">About MCP</a></p><hr><h2 id="cloud-agent" tabindex="-1">Cloud agent <a class="header-anchor" href="#cloud-agent" aria-label="Permalink to &quot;Cloud agent&quot;">​</a></h2><p><strong>What it is</strong>: a Copilot agent that runs in GitHub&#39;s cloud. You assign a task from an Issue or the web UI; it opens a branch, edits, optionally verifies, and can open a Pull Request.</p><p><strong>Versus Chat Agent mode</strong>:</p><table tabindex="0"><thead><tr><th>Axis</th><th>Chat Agent mode</th><th>Cloud agent</th></tr></thead><tbody><tr><td>Where it runs</td><td>Your local editor</td><td>GitHub cloud</td></tr><tr><td>Do you watch?</td><td>Yes (you approve tool calls)</td><td>No; you get notified</td></tr><tr><td>Artifact</td><td>Working-tree edits</td><td>Usually a Pull Request</td></tr><tr><td>Fit</td><td>Exploratory work you want to steer</td><td>A job you can state in one paragraph</td></tr></tbody></table><p><strong>Why it exists</strong>: a local agent occupies your editor and attention. &quot;Replace the old API in these 30 files&quot; is well-scoped and slow — cheaper to run in the cloud and review a PR.</p><p><strong>2026-04-01 expansion</strong> (<a href="https://github.blog/changelog/2026-04-01-research-plan-and-code-with-copilot-cloud-agent/" target="_blank" rel="noreferrer">changelog</a>): it is no longer limited to &quot;always open a PR.&quot; It can research the repo, produce a plan for approval, and work on a branch until you click Create pull request. Paid plans; Business / Enterprise need an admin to enable it.</p><p><strong>It used to be called &quot;coding agent.&quot;</strong> Old &quot;Copilot coding agent&quot; pages mean this product.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent" target="_blank" rel="noreferrer">About GitHub Copilot cloud agent</a></p><hr><h2 id="copilot-app" tabindex="-1">Copilot app <a class="header-anchor" href="#copilot-app" aria-label="Permalink to &quot;Copilot app&quot;">​</a></h2><p><strong>What it is</strong>: a desktop application for agent-driven development. It sits on top of Copilot CLI and gives you parallel agent sessions, GitHub Issues / pull requests, and scheduled automations in one window.</p><p><strong>Versus IDE Chat / the CLI</strong>:</p><table tabindex="0"><thead><tr><th>Axis</th><th>IDE Chat</th><th>Copilot CLI</th><th>Copilot app</th></tr></thead><tbody><tr><td>Where</td><td>Inside the editor</td><td>Terminal</td><td>Its own desktop window</td></tr><tr><td>Parallel work</td><td>One conversation at a time is the default</td><td>One session per terminal</td><td>First-class parallel workspaces</td></tr><tr><td>Fit</td><td>You are already editing files</td><td>You live in the shell</td><td>You want to direct several agents and stay out of the IDE</td></tr></tbody></table><p><strong>Availability</strong>: all Copilot plans. Business / Enterprise need the Copilot app policy left on (it is on by default, and it is separate from the Copilot CLI policy).</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/concepts/agents/github-copilot-app" target="_blank" rel="noreferrer">About the GitHub Copilot app</a></p><hr><h2 id="copilot-spaces" tabindex="-1">Copilot Spaces <a class="header-anchor" href="#copilot-spaces" aria-label="Permalink to &quot;Copilot Spaces&quot;">​</a></h2><p><strong>What it is</strong>: a named pack of related context (repos, files, free text, attachments). Questions asked against that Space always carry the pack.</p><p><strong>Why it exists</strong>: custom instructions solve &quot;constant project rules.&quot; Spaces solve &quot;the knowledge pack for one topic&quot; — e.g. &quot;payments domain&quot; = three repos + an architecture note + a glossary. That pack should not live in global instructions (irrelevant to other work) and is too heavy to cite by hand every time.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/concepts/context/spaces" target="_blank" rel="noreferrer">About Copilot Spaces</a></p><hr><h2 id="copilot-cli" tabindex="-1">Copilot CLI <a class="header-anchor" href="#copilot-cli" aria-label="Permalink to &quot;Copilot CLI&quot;">​</a></h2><p><strong>What it is</strong>: Copilot as a terminal agent. <strong>Two different products share the nickname — do not mix them:</strong></p><table tabindex="0"><thead><tr><th></th><th>Old: <code>gh copilot</code></th><th>New: <code>copilot</code></th></tr></thead><tbody><tr><td>Shape</td><td>A <code>gh</code> CLI extension</td><td>A standalone binary</td></tr><tr><td>Install</td><td><code>gh extension install github/gh-copilot</code></td><td><code>npm install -g @github/copilot</code> (and others)</td></tr><tr><td>Capability</td><td><code>explain</code> / <code>suggest</code> only</td><td>Full interactive agent: files, commands, MCP, plugins</td></tr><tr><td>Interaction</td><td>One question, one answer</td><td>A session with permission modes, slash commands, resume</td></tr></tbody></table><p><strong>Why two</strong>: <code>gh copilot</code> was a light &quot;help me remember the command&quot; experiment. Standalone <code>copilot</code> is the full agent moved into the terminal. GitHub has marked the former <strong>retired</strong>. &quot;Copilot CLI&quot; today means only the latter.</p><p><strong>Permission modes</strong>: the CLI really runs commands and really edits files, so it has graded authorization (ask by default / assisted / allow all) plus allow/deny rules by command and path. That is the difference from a chat box: it has side effects.</p><p><strong>Commands, flags, keys</strong>: <a href="./copilot-cheatsheet.html">Cheatsheet · Copilot CLI</a>.</p><p><strong>Official</strong>:</p><ul><li><a href="https://docs.github.com/en/copilot/how-tos/copilot-cli/install-copilot-cli" target="_blank" rel="noreferrer">Install Copilot CLI</a></li><li><a href="https://docs.github.com/en/copilot/reference/cli-command-reference" target="_blank" rel="noreferrer">CLI command reference</a></li></ul><hr><h2 id="ai-credits-and-quotas" tabindex="-1">AI credits and quotas <a class="header-anchor" href="#ai-credits-and-quotas" aria-label="Permalink to &quot;AI credits and quotas&quot;">​</a></h2><p><strong>What they are</strong>: Copilot&#39;s usage unit. Each paid plan includes a pool of GitHub AI credits. High-cost features (Chat, CLI, agents, code review) spend credits. Basic completions have their own rules per plan (Free: 2,000 / month).</p><p><strong>Why you should care</strong>: this is what decides &quot;can I leave Agent mode on all day?&quot; Completion is almost free; agent work is metered. &quot;Prefer completion when it is enough&quot; is a cost rule, not only a UX rule.</p><p><strong>The billing model moved</strong>: the plans page marks request-count &quot;premium requests&quot; as legacy. Current language is AI credits. &quot;X premium requests per month&quot; in old tutorials is stale.</p><p><strong>Business vs Enterprise pools</strong> (official enterprise-plan page): Business <strong>1,900</strong> credits / user, Enterprise <strong>3,900</strong>, pooled across the org. See <a href="./copilot-cheatsheet.html">Cheatsheet · Plan comparison</a>.</p><p><strong>Official</strong>: <a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">Copilot plans</a></p><hr><h2 id="retired-or-renamed-concepts" tabindex="-1">Retired or renamed concepts <a class="header-anchor" href="#retired-or-renamed-concepts" aria-label="Permalink to &quot;Retired or renamed concepts&quot;">​</a></h2><p>Copilot moves fast. You will meet these names in old tutorials (including this site&#39;s previous single file). <strong>They do not apply today:</strong></p><table tabindex="0"><thead><tr><th>Old name</th><th>Status</th><th>Replacement</th></tr></thead><tbody><tr><td><strong>Copilot Workspace</strong> (GitHub Next technical preview)</td><td>Sunset <strong>2025-05-30</strong>, official note on <a href="https://githubnext.com/projects/copilot-workspace/" target="_blank" rel="noreferrer">GitHub Next</a> and the <a href="https://gh.io/copilot-workspace-sunset" target="_blank" rel="noreferrer">sunset notice</a></td><td>Cloud agent carries &quot;describe an Issue, get a PR&quot;</td></tr><tr><td><strong>GitHub Spark</strong></td><td>No new users / no new apps from <strong>2026-08-04</strong>; existing users can export until <strong>2026-08-31</strong>. <a href="https://github.blog/changelog/2026-08-04-upcoming-deprecation-of-github-spark-on-github-com/" target="_blank" rel="noreferrer">Changelog</a></td><td>Build in the IDE, Copilot CLI, or Copilot app. Deployed Spark apps keep running</td></tr><tr><td><strong>Copilot Extensions</strong> (GitHub App form)</td><td>Fully sunset <strong>2025-11-10</strong>, <a href="https://github.blog/changelog/2025-09-24-deprecate-github-copilot-extensions-github-apps/" target="_blank" rel="noreferrer">announcement</a></td><td>MCP servers. <strong>VS Code client-side Chat extensions remain supported</strong> — the announcement excludes them</td></tr><tr><td><strong><code>@workspace</code></strong></td><td>Off the VS Code participant list</td><td>Codebase search is a tool; Agent mode calls it. To force it, <code>#search</code> (includes <code>/codebase</code>)</td></tr><tr><td><strong><code>@regex</code></strong></td><td>Not on the official list; likely an early community participant</td><td>Just ask in Ask mode</td></tr><tr><td><strong><code>#editor</code> / <code>#git</code> / <code>#vscodeAPI</code></strong></td><td>No longer standalone variables</td><td><code>#read</code> (editor contents), <code>#search</code> (<code>/changes</code>), <code>#vscode</code> (<code>/VSCodeAPI</code>)</td></tr><tr><td><strong><code>/new-from</code></strong></td><td>Not on any official list; <strong>the old file invented this row</strong></td><td><code>/new</code> for a project, <code>/newNotebook</code> for a notebook</td></tr><tr><td><strong><code>/runCommand</code> as a slash command</strong></td><td>Not a top-level slash command</td><td><code>#vscode</code> tool <code>/runCommand</code></td></tr><tr><td><strong>Custom chat modes</strong></td><td>Renamed</td><td>Custom agents</td></tr><tr><td><strong>Copilot coding agent</strong></td><td>Renamed</td><td>Cloud agent</td></tr><tr><td><strong>&quot;<code>gh copilot</code> is Copilot&#39;s CLI&quot;</strong></td><td><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-for-common-tasks/use-copilot-in-the-cli" target="_blank" rel="noreferrer">Officially retired</a></td><td>Standalone <code>copilot</code> CLI</td></tr><tr><td><strong>Premium requests (count-based quota)</strong></td><td>Marked legacy on the plans page</td><td>AI credits</td></tr><tr><td><strong><code>docs.github.com/zh/enterprise-cloud@latest/...</code></strong></td><td>Widely 404 / redirect</td><td><code>docs.github.com/en/copilot/...</code></td></tr></tbody></table><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./copilot.html">Copilot tutorial</a> — install, first run, four surfaces</li><li><a href="./copilot-cheatsheet.html">Copilot Cheatsheet</a> — keys / commands / config / plans / sources</li><li><a href="./copilot-cookbook.html">Cookbook</a> — scenario recipes</li></ul>`,143)])])}const b=e(n,[["render",r]]);export{f as __pageData,b as default};
